let craftUI=null;const hotbar=document.querySelector('#hotbar'),label=document.querySelector('#label');let selected=0;types.forEach(([name,color],i)=>{let b=document.createElement('button');b.className='slot';b.title=name;b.innerHTML=`<span>${i+1}</span><div class="cube" style="background:#${color.toString(16).padStart(6,'0')}"></div><b class="count"></b>`;b.onclick=()=>select(i);hotbar.append(b)});function select(i){selected=(i+types.length)%types.length;[...hotbar.children].forEach((b,j)=>b.classList.toggle('active',j===selected));label.textContent=types[selected][0]}function refreshStock(){[...hotbar.children].forEach((b,i)=>{b.querySelector('.count').textContent=stock[i];b.setAttribute('aria-label',`${types[i][0]}、のこり${stock[i]}個`);b.classList.toggle('empty',stock[i]===0)});if(craftUI)craftUI.refresh()}select(0);refreshStock();
