const outline=new THREE.LineSegments(new THREE.EdgesGeometry(geo),new THREE.LineBasicMaterial({color:0xffffff,transparent:true,opacity:.8}));outline.scale.setScalar(1.008);scene.add(outline);let pos=new THREE.Vector3(0,height(0,6)+3,6),vel=0,onGround=false;function solid(x,y,z){return world.has(key(Math.floor(x+.5),Math.floor(y+.5),Math.floor(z+.5)))}function collides(x,y,z){for(let dx of [-.28,.28])for(let dz of [-.28,.28])for(let dy of [-1.55,-.8,-.1])if(solid(x+dx,y+dy,z+dz))return true;return false}let last=performance.now();function animate(now){requestAnimationFrame(animate);let dt=Math.min((now-last)/1000,.05);last=now;if(playing){let f=(keys.KeyW?1:0)-(keys.KeyS?1:0)-joyY,s=(keys.KeyD?1:0)-(keys.KeyA?1:0)+joyX,len=Math.max(1,Math.hypot(f,s));let speed=(keys.ShiftLeft?7:4.5)*dt;let dx=(-Math.sin(yaw)*f+Math.cos(yaw)*s)/len*speed,dz=(-Math.cos(yaw)*f-Math.sin(yaw)*s)/len*speed;if(!collides(pos.x+dx,pos.y,pos.z))pos.x+=dx;if(!collides(pos.x,pos.y,pos.z+dz))pos.z+=dz;if((keys.Space||touchJump)&&onGround){vel=7;onGround=false}vel-=19*dt;let ny=pos.y+vel*dt;if(!collides(pos.x,ny,pos.z)){pos.y=ny;onGround=false}else{if(vel<0)onGround=true;vel=0}if(pos.y< -10){pos.set(0,height(0,6)+4,6);vel=0}}mobs.update(dt,playing,mode==='solo'||mode==='host',peerAvatar.visible?peerAvatar.position:null);breakParticles.update(dt);camera.position.copy(pos);const shake=updateDamageFeedback(dt);camera.position.x+=shake.x;camera.position.y+=shake.y;updateScenery(camera);camera.rotation.order='YXZ';camera.rotation.y=yaw;camera.rotation.x=pitch;camera.rotation.z=shake.roll;let h=target();outline.visible=!!h;if(h)outline.position.set(...h.p);renderer.render(scene,camera)}requestAnimationFrame(animate);addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});

