const mobButton=document.createElement('button');mobButton.className='tool mob-toggle';document.querySelector('.topright').prepend(mobButton);function refreshMobButton(){mobButton.textContent='モブ：'+(mobs.isEnabled()?'ON':'OFF')}refreshMobButton();mobButton.onclick=()=>{if(multi.isGuest()){message('モブの設定はホストが変更します');return}if(multi.isActive()&&multi.getRole()!=='host'){message('接続の準備中です');return}mobs.enable(!mobs.isEnabled());refreshMobButton();multi.broadcastMob();message(mobs.isEnabled()?'スライムがあらわれた！':'モブをおやすみしました')};
